210	    /**
211	     * Create and persist a brand-new owner from the supplied fields, returning the
212	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
213	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily,
214	     * city and household gates (each with its own rejection status), resolve any household,
215	     * {@link #assignDerivedAttributes derive the create-time attributes}, save, audit and
216	     * build the response with its {@code Location} header — so {@link #addOwner} itself
217	     * stays a thin entry point.
218	     *
219	     * @param ownerFieldsDto the owner fields from the request body
220	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
221	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
222	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
223	     *         reached, or {@code 409 Conflict} when the city is at capacity or the owner
224	     *         joins an existing household without declaring {@code sharesHousehold}
225	     */
226	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
229	        if (!normalizeNewOwner(owner)) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        if (dailyLimitReached(owner.getRegistrationDate())) {
233	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
234	        }
235	        if (cityIsAtCapacity(owner.getCity())) {
236	            return new ResponseEntity<>(HttpStatus.CONFLICT);
237	        }
238	        owner.setHouseholdId(owner.computeHouseholdId());
239	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
240	        Optional<Owner> householdMember = findHouseholdMember(owner);
241	        if (householdMember.isPresent() && !sharesHousehold) {
242	            return new ResponseEntity<>(HttpStatus.CONFLICT);
243	        }
244	        boolean declaredHouseholdMember = householdMember.isPresent();
245	        assignDerivedAttributes(owner, declaredHouseholdMember);
246	        this.clinicService.saveOwner(owner);
247	        auditOwnerCreated(owner);
248	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
249	        headers.setLocation(UriComponentsBuilder.newInstance()
250	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
251	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
252	    }
253	
254	    /**
255	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
256	     * the canonical form each stored value must take: the address is trimmed,
257	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
258	     * telephone is converted to E.164, any email is lower-cased and a missing
259	     * registration date defaults to today. Field-level rejections are reported here
260	     * rather than inline in {@link #addOwner}, and normalisation runs before any
261	     * household comparison so those comparisons see the canonical values.
262	     *
263	     * @param owner the freshly-mapped owner to normalise
264	     * @return {@code true} if the fields are valid, or {@code false} if the address
265	     *         is blank after normalisation, the telephone cannot form a valid
266	     *         E.164 number, or a supplied registration date is later than the
267	     *         server date, in which case the request must be rejected with
268	     *         {@code 400 Bad Request}
269	     */
270	    private boolean normalizeNewOwner(Owner owner) {
271	        if (!normalizeAddressFields(owner)) {
272	            return false;
273	        }
274	        String telephone = Telephones.toE164(owner.getTelephone());
275	        if (telephone == null) {
276	            return false;
277	        }
278	        owner.setTelephone(telephone);
279	        if (owner.getEmail() != null) {
280	            String email = owner.getEmail().toLowerCase();
281	            owner.setEmail(email);
282	            if (emailDomainIsBlocked(email)) {
283	                return false;
284	            }
285	        }
286	        if (!owner.postcodeValidForLocality()) {
287	            return false;
288	        }
289	        if (owner.getRegistrationDate() == null) {
290	            owner.setRegistrationDate(LocalDate.now());
291	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
292	            return false;
293	        }
294	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
295	        return true;
296	    }
297	
298	    /**
299	     * Normalise the owner's address fields in place to their canonical stored form
300	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
301	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
302	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
303	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
304	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
305	     * them — the normalised {@code addressLine1}, with a single space and the normalised
306	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
307	     * flat {@code address} is normalised on its own, preserving backward compatibility.
308	     * Either way the canonicalised values are written back so every later household
309	     * comparison and read sees them.
310	     *
311	     * @param owner the freshly-mapped owner whose address fields are being normalised
312	     * @return {@code true} once an address is valid and stored, or {@code false} when
313	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
314	     *         present after normalisation, in which case the request must be rejected
315	     *         with {@code 400 Bad Request}
316	     */
317	    private boolean normalizeAddressFields(Owner owner) {
318	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
319	        if (!addressLine1.isEmpty()) {
320	            owner.setAddressLine1(addressLine1);
321	            String composed = addressLine1;
322	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
323	            if (!addressLine2.isEmpty()) {
324	                owner.setAddressLine2(addressLine2);
325	                composed = addressLine1 + " " + addressLine2;
326	            }
327	            owner.setAddress(composed);
328	            return true;
329	        }
330	        String address = Owner.normalizeAddress(owner.getAddress());
331	        if (address.isEmpty()) {
332	            return false;
333	        }
334	        owner.setAddress(address);
335	        return true;
336	    }
337	
338	    /**
339	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
340	     * email address is on one of these domains is rejected with {@code 400 Bad
341	     * Request} rather than created.
342	     */
343	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
344	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
345	
346	    /**
347	     * Whether the given (already lower-cased) email address belongs to a disposable
348	     * mailbox domain on the blocklist. The domain is the part after the final
349	     * {@code '@'}; an address without one is treated as having no blocked domain.
350	     *
351	     * @param email the owner's normalised (lower-cased) email address
352	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
353	     */
354	    private static boolean emailDomainIsBlocked(String email) {
355	        int at = email.lastIndexOf('@');
356	        if (at < 0) {
357	            return false;
358	        }
359	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
360	    }
361	
362	    /**
363	     * The fixed list of public holidays on which the clinic is closed. A registration
364	     * date that lands on one of these dates is treated the same as a weekend and rolled
365	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
366	     */
367	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
368	        LocalDate.of(2026, 1, 1),
369	        LocalDate.of(2026, 1, 26),
370	        LocalDate.of(2026, 4, 25),
371	        LocalDate.of(2026, 12, 25),
372	        LocalDate.of(2026, 12, 28));
373	
374	    /**
375	     * Roll the given date forward to the next business day when it falls on a weekend or
376	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
377	     * at a time until a non-holiday weekday is reached, while a plain business day is
378	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
379	     * versa), the advance repeats until the date is neither. Applied to the effective
380	     * registration date (whether supplied in the request or defaulted to the server date)
381	     * so that every value derived from it uses the adjusted business day.
382	     *
383	     * @param date the effective registration date
384	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
385	     */
386	    private static LocalDate rollToBusinessDay(LocalDate date) {
387	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
388	            date = date.plusDays(1);
389	        }
390	        return date;
391	    }
392	
393	    /**
394	     * Whether the given date falls on a weekend (Saturday or Sunday).
395	     */
396	    private static boolean isWeekend(LocalDate date) {
397	        return switch (date.getDayOfWeek()) {
398	            case SATURDAY, SUNDAY -> true;
399	            default -> false;
400	        };
401	    }
402	
403	    /**
404	     * Find an existing owner that belongs to the same household as the given owner,
405	     * i.e. shares the same last name (compared case-insensitively with runs of
406	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
407	     * deterministic {@code householdId}.
408	     *
409	     * @param owner the candidate owner being created
410	     * @return the matching existing owner, or empty if none exists
411	     */
412	    private Optional<Owner> findHouseholdMember(Owner owner) {
413	        return this.clinicService.findAllOwners().stream()
414	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()))
415	            .filter(existing -> existing.sameHouseholdAs(owner))
416	            .findFirst();
417	    }
418	
419	    /**
420	     * Assign the owner's computed-at-creation attributes in place: its customer code,
421	     * namesake count, membership number, bulk-signup warning and household size. Unlike
422	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
423	     * derived once here — from the owner's own (already normalised) fields and from the
424	     * wider owner population — and persisted with the owner. Run after normalisation,
425	     * household resolution and the identity-key check, so every value reflects the
426	     * owner's final field values and any household it has joined, and immediately before
427	     * the owner is saved.
428	     *
429	     * <p>Ordering matters: the customer code is assigned first because the membership
430	     * number is built from it.
431	     *
432	     * @param owner the candidate owner being created, after household resolution
433	     * @param declaredHouseholdMember whether this owner was created as a declared member
434	     *                                of an existing household (it shared an existing
435	     *                                owner's household and set {@code sharesHousehold}),
436	     *                                in which case it is not a suspected duplicate
437	     */
438	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
439	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
440	        owner.setNamesakeCount(countNamesakes(owner));
441	        owner.setMembershipNumber(owner.computeMembershipNumber());
442	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
443	        owner.setHouseholdSize(householdSize(owner));
444	        assignPossibleDuplicate(owner, declaredHouseholdMember);
445	    }
446	
447	    /**
448	     * Compute the customer code to assign to the candidate owner, de-duplicated against
449	     * every existing owner's customer code. The base code is the owner's computed
450	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
451	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
452	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
453	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
454	     * before the owner is saved, so only pre-existing owners are considered.
455	     *
456	     * @param owner the candidate owner being created, after normalisation
457	     * @return the unique (de-duplicated) customer code to assign
458	     */
459	    private String deduplicatedCustomerCode(Owner owner) {
460	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
461	            .map(Owner::getCustomerCode)
462	            .filter(code -> code != null)
463	            .collect(java.util.stream.Collectors.toSet());
464	        String base = owner.computeCustomerCode();
465	        if (!existingCodes.contains(base)) {
466	            return base;
467	        }
468	        int n = 2;
469	        while (existingCodes.contains(base + "-" + n)) {
470	            n++;
471	        }
472	        return base + "-" + n;
473	    }
474	
475	    /**
476	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
477	     * match is an existing owner that shares this owner's last name (compared
478	     * case-insensitively) and postcode but carries a different (normalised) telephone.
479	     * When such a match exists the owner is still created, but with
480	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
481	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
482	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
483	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
484	     * are considered.
485	     *
486	     * <p>A declared household member — one that shared an existing owner's household
487	     * (same last name and postcode) and was admitted because it set
488	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
489	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
490	     *
491	     * @param owner the candidate owner being created, after household resolution
492	     * @param declaredHouseholdMember whether the owner is a declared household member
493	     */
494	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
495	        if (declaredHouseholdMember) {
496	            owner.setPossibleDuplicate(false);
497	            owner.setPossibleDuplicateOf(null);
498	            return;
499	        }
500	        String lastName = normalizeName(owner.getLastName());
501	        String postcode = owner.getPostcode();
502	        String telephone = owner.getTelephone();
503	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
504	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
505	                && normalizeName(existing.getLastName()).equals(lastName)
506	                && telephone != null && !telephone.equals(existing.getTelephone()))
507	            .min(Comparator.comparing(Owner::getId));
508	        if (match.isPresent()) {
509	            owner.setPossibleDuplicate(true);
510	            owner.setPossibleDuplicateOf(match.get().getId());
511	        } else {
512	            owner.setPossibleDuplicate(false);
513	            owner.setPossibleDuplicateOf(null);
514	        }
515	    }
516	
517	    /**
518	     * Count how many owners belong to the given owner's household once this create
519	     * completes: the owners that already share its deterministic {@code householdId}
520	     * (derived from last name and postcode) plus the owner being created. Evaluated
521	     * after the owner's {@code householdId} has been assigned. An owner whose
522	     * {@code householdId} matches no existing owner is a household of one.
523	     *
524	     * @param owner the candidate owner being created, after household resolution
525	     * @return the household member count after this create (at least {@code 1})
526	     */
527	    private int householdSize(Owner owner) {
528	        String householdId = owner.getHouseholdId();
529	        if (householdId == null) {
530	            return 1;
531	        }
532	        long existing = this.clinicService.findAllOwners().stream()
533	            .filter(other -> householdId.equals(other.getHouseholdId()))
534	            .count();
535	        return (int) existing + 1;
536	    }
537	
538	    /**
539	     * Count the existing owners that share the given owner's first and last name,
540	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
541	     * before the new owner is saved, so the result reflects only owners that
542	     * already existed at creation time.
543	     *
544	     * @param owner the candidate owner being created
545	     * @return the number of existing namesakes
546	     */
547	    private int countNamesakes(Owner owner) {
548	        String firstName = normalizeName(owner.getFirstName());
549	        String lastName = normalizeName(owner.getLastName());
550	        return (int) this.clinicService.findAllOwners().stream()
551	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
552	                && normalizeName(existing.getLastName()).equals(lastName))
553	            .count();
554	    }
555	
556	    private static String normalizeName(String value) {
557	        return value == null ? "" : value.trim().toLowerCase();
558	    }
559	
560	    /**
561	     * Determine whether the given city has already reached its owner capacity, i.e.
562	     * it already contains 50 or more existing owners (compared case-insensitively
563	     * with surrounding whitespace trimmed). A new owner may not be created in a city
564	     * that is at capacity.
565	     *
566	     * @param city the candidate owner's city
567	     * @return {@code true} if the city already holds 50 or more owners
568	     */
569	    private boolean cityIsAtCapacity(String city) {
570	        String normalizedCity = normalizeName(city);
571	        long count = this.clinicService.findAllOwners().stream()
572	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
573	            .count();
574	        return count >= 50;
575	    }
576	
577	    /**
578	     * Determine whether the daily owner-creation limit has already been reached, i.e.
579	     * 100 or more owners already carry the given registration date. A new owner may
580	     * not be created once that day's cap is reached.
581	     *
582	     * @param registrationDate the registration date the new owner would be created with
583	     * @return {@code true} if 100 or more existing owners share that registration date
584	     */
585	    private boolean dailyLimitReached(LocalDate registrationDate) {
586	        long count = this.clinicService.findAllOwners().stream()
587	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
588	            .count();
589	        return count >= 100;
590	    }
591	
592	    /**
593	     * Determine whether more than 80 owners have already been created for the given
594	     * registration date, i.e. strictly more than 80 existing owners carry that date.
595	     * Evaluated before the new owner is saved, so it reflects only owners that
596	     * already existed at creation time.
597	     *
598	     * @param registrationDate the registration date the new owner would be created with
599	     * @return {@code true} if more than 80 existing owners share that registration date
600	     */
601	    private boolean bulkSignupWarning(LocalDate registrationDate) {
602	        long count = this.clinicService.findAllOwners().stream()
603	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
604	            .count();
605	        return count > 80;
606	    }
607	
608	    /**
609	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
610	     * one place so it stays in step with the owner's identity: it reports the assigned
611	     * customer code alongside the owner's id, registration date, membership level and
612	     * membership number.
613	     *
614	     * @param owner the owner that has just been created and saved
615	     */
616	    private void auditOwnerCreated(Owner owner) {
617	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
618	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
619	            owner.getMembershipNumber());
620	    }
621	}
